      pkgs.jq
    ];
    text = builtins.readFile ../scripts/moraine-service;
  };
  moraineConfig = ''
    [identity]
    author = "faviann@gmail.com"

    [ingest]
    backfill_on_start = true

    [[ingest.sources]]
    name = "codex-active"
    harness = "codex"
    enabled = true
    glob = "~/.codex/sessions/**/*.jsonl"
    watch_root = "~/.codex/sessions"

    [[ingest.sources]]
    name = "codex-archived"
    harness = "codex"
    enabled = true
    glob = "~/.codex/archived_sessions/*.jsonl"
    watch_root = "~/.codex/archived_sessions"

    [[ingest.sources]]
    # Do not use upstream's setup-owned `claude` signature: v0.7.3 treats an
    # exact match as legacy generated config and injects newer default sources.
    name = "claude-projects"
    harness = "claude-code"
    enabled = true
    glob = "~/.claude/projects/**/*.jsonl"
    watch_root = "~/.claude/projects"

    [runtime]
    root_dir = "${moraineRoot}"
    service_bin_dir = "${morainePackage}/bin"
    managed_clickhouse_dir = "${moraineRoot}/clickhouse/current"
  '';
in
{
  home.username = "faviann";
  home.homeDirectory = "/home/faviann";
  home.stateVersion = "25.11";

  programs.home-manager.enable = true;

  home.packages = with pkgs; [
    dotnetSdk
    nodejs
    uv
    gh
    jq
    ripgrep
    fd
    fzf
    hermesPackage
    morainePackage
  ];

  home.sessionPath = [
    "$HOME/.local/bin"
  ];

  home.file.${moraineConfigRelative}.text = moraineConfig;

  home.activation.removeLegacyAoeUnits = lib.hm.dag.entryBefore [ "writeBoundary" ] ''
    rm -f \
      "$HOME/.config/systemd/user/aoe-serve.service" \
      "$HOME/.config/systemd/user/aoe-lan-proxy.service" \
      "$HOME/.config/systemd/user/aoe-lan-proxy.socket"
  '';

  systemd.user.startServices = "sd-switch";

  # Upstream owns installation, readiness, migrations, and child startup. The
  # foreground wrapper keeps this unit alive only while that complete stack is
  # healthy, so one restart policy accurately represents the operator surface.
  systemd.user.services.moraine = {
    Unit = {
      Description = "Workstation-local Moraine producer";
      X-Restart-Triggers = [ config.home.file.${moraineConfigRelative}.source ];
    };

    Service = {
      Type = "simple";
      ExecStart = "${moraineService}/bin/moraine-service ${morainePackage}/bin/moraine ${moraineConfigPath}";
      ExecStop = "${moraineControl} down";
      Restart = "on-failure";
      RestartSec = 5;
    };

    Install.WantedBy = [ "default.target" ];
  };

  # installPackages is what creates the profile this handoff reads from. Ordered
  # only after reloadSystemd, the handoff ran while ~/.nix-profile was still a
  # dangling symlink, so every home.packages tool the updater needs — npm, jq —
  # was missing and activation died on whichever one it probed first.
  home.activation.bootstrapAgentTools =
    lib.hm.dag.entryAfter [ "reloadSystemd" "installPackages" ] ''
      # Activation runs with a curated store-only PATH holding just coreutils and
      # friends, so system directories are absent. The updater's remaining host
      # tools — flock for its lock, curl for the AoE release check, unzip and find
      # for the Bun archive — come from the store rather than from whatever the
      # host happens to install.
      #
      # The system directories go last, after everything the store supplies, for
      # systemctl alone: the updater restarts a unit in this host's user session,
      # so it needs that session's own systemd rather than a store copy of one.
      export PATH="$HOME/.local/bin:${config.home.profileDirectory}/bin:${updaterHostTools}:$PATH:/usr/local/bin:/usr/bin:/bin"

      # bun is listed because the updater owns it: nixpkgs lags Bun releases badly
      # enough that a harness engine floor can outrun it, so a switch that finds
      # no bun must hand off rather than leave the harnesses without a runtime.
      _agent_tools_missing=false
      for _agent_tool in \
        aoe bun codex claude pi opencode omp codex-acp claude-agent-acp pi-acp; do
        if ! command -v "$_agent_tool" >/dev/null 2>&1; then
          _agent_tools_missing=true
          break
        fi
      done

      if [ "$_agent_tools_missing" = true ]; then
        command -v aoe >/dev/null 2>&1 \
          || { echo "Agent-tool bootstrap requires chezmoi to install AoE first" >&2; exit 1; }
        command -v update-agent-tools >/dev/null 2>&1 \
          || { echo "Agent-tool bootstrap requires the dotfiles updater" >&2; exit 1; }
        update-agent-tools --yes
      fi
    '';

  systemd.user.services.aoe-serve = {
    Unit = {
      Description = "Agent of Empires web dashboard";
      After = [ "default.target" ];
      # aoe-serve binds 127.0.0.1:4000; the portal reaches it only through the
      # socket-activated proxy on 4001. Starting the app without the socket leaves
      # the origin port unbound, which looks like an application fault from the
      # portal side. Wants, not Requires: the app is still useful locally if the
      # socket fails, and Wants adds no ordering to deadlock against the proxy's
      # own Requires=aoe-serve.service.
      Wants = [ "aoe-lan-proxy.socket" ];
    };

    Service = {
      Type = "simple";
      Environment = "PATH=%h/.local/bin:%h/.nix-profile/bin:/usr/local/bin:/usr/bin:/bin";
      ExecStart = "/usr/bin/env aoe serve --host 127.0.0.1 --port 4000 --no-auth --behind-proxy --allowed-host aoe.local.faviann.com";
      Restart = "on-failure";
      RestartSec = 5;
    };

    Install.WantedBy = [ "default.target" ];
  };

  systemd.user.services.aoe-lan-proxy = {
    Unit = {
      Description = "AoE LAN proxy";
      Requires = [ "aoe-serve.service" ];
      After = [ "aoe-serve.service" ];
    };

    Service.ExecStart = "/lib/systemd/systemd-socket-proxyd 127.0.0.1:4000";
  };

  systemd.user.sockets.aoe-lan-proxy = {
    Unit.Description = "AoE LAN proxy socket";

    Socket = {
      ListenStream = "0.0.0.0:4001";
      NoDelay = true;
    };

    Install.WantedBy = [ "sockets.target" ];
  };

  systemd.user.sockets.collie-origin-forwarder = {
    Socket.ListenStream = "0.0.0.0:8788";
    Install.WantedBy = [ "sockets.target" ];
  };

  systemd.user.services.collie-origin-forwarder.Service.ExecStart =
    "/lib/systemd/systemd-socket-proxyd 127.0.0.1:8787";

  # Collie's own unit is generated by collie-ctl and is deliberately not declared
  # here, so the socket link cannot be expressed the way aoe-serve expresses it.
  # A drop-in appends one orthogonal line without duplicating any of the generated
  # unit's contents, so Collie can keep regenerating collie.service on upgrade
  # without dropping the link or drifting from a forked copy.
  #
  # The dependency deliberately points app -> socket. The reverse, a
  # Requires=collie.service on the forwarder, would make this configuration
  # reference a unit it does not manage and would fail whenever Collie is not
  # installed. That is why collie-origin-forwarder stays free of Collie
  # dependencies, and why the test asserting so still holds.
  xdg.configFile."systemd/user/collie.service.d/10-origin-forwarder.conf".text = ''
    [Unit]
    Wants=collie-origin-forwarder.socket
  '';

  systemd.user.services.hermes-gateway = {
    Unit = {
      Description = "Hermes Agent gateway";
      After = [ "default.target" ];
    };
    Service = {
      Type = "simple";
      Environment = "PATH=%h/.local/bin:%h/.nix-profile/bin:/usr/local/bin:/usr/bin:/bin";
      ExecStart = "/usr/bin/env hermes gateway run";
      Restart = "on-failure";
      RestartSec = 10;
    };
    Install.WantedBy = [ "default.target" ];
  };

  systemd.user.services.hermes-dashboard = {
    Unit = {
      Description = "Hermes Agent dashboard";
      Requires = [ "hermes-gateway.service" ];
      After = [ "default.target" "hermes-gateway.service" ];
    };
    Service = {
      Type = "simple";
      Environment = "PATH=%h/.local/bin:%h/.nix-profile/bin:/usr/local/bin:/usr/bin:/bin";
      ExecStart = "/usr/bin/env hermes dashboard --host 0.0.0.0 --port 9119 --no-open --insecure";
      Restart = "on-failure";
      RestartSec = 10;
    };
    Install.WantedBy = [ "default.target" ];
  };

  programs.openclaw = {
    enable = true;
    stateDir = "${config.home.homeDirectory}/.openclaw";
    systemd.enable = true;
    systemd.unitName = "openclaw-gateway";
  };

  # The nix-openclaw module writes openclaw.json as a read-only nix-store symlink,
  # which prevents openclaw from persisting runtime state (auth tokens, model choices, etc.).
  # These two hooks bracket nix-openclaw's generated config link:
  # save it before Home Manager writes links, restore it after openclawConfigFiles.
  home.activation.openclawSaveConfig = lib.hm.dag.entryBefore [ "writeBoundary" ] ''
    _oc_config="${config.programs.openclaw.stateDir}/openclaw.json"
    _oc_saved="${config.programs.openclaw.stateDir}/openclaw.json.pre-hm"
    if [ -f "$_oc_config" ] && [ ! -L "$_oc_config" ]; then
      cp "$_oc_config" "$_oc_saved"
    fi
#!/usr/bin/env bash
set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
readonly REPO_ROOT

fail() {
  printf 'FAIL: %s\n' "$*" >&2
  exit 1
}

rendered_json() {
  local fixture_filter="$1"
  local installable="$2"
  shift 2

  if [[ -n "${TEST_WORKSTATION_RENDERED_CONFIGURATION:-}" ]]; then
    jq -ce "$fixture_filter" "$TEST_WORKSTATION_RENDERED_CONFIGURATION"
    return
  fi

  nix eval --json "$installable" "$@"
}

rendered_raw() {
  local fixture_filter="$1"
  local installable="$2"

  if [[ -n "${TEST_WORKSTATION_RENDERED_CONFIGURATION:-}" ]]; then
    jq -er "$fixture_filter" "$TEST_WORKSTATION_RENDERED_CONFIGURATION"
    return
  fi

  nix eval --raw "$installable"
}

test_workstation_profile_includes_dotnet_10_lts_sdk() {
  local dotnet_sdk_package

  dotnet_sdk_package="$(
    rendered_json '.dotnetSdkPackage' \
      "$REPO_ROOT#homeConfigurations.workstation.config.home.packages" \
      --apply '
        packages:
        let
          package = builtins.head (
            builtins.filter
              (package: (package.pname or package.name) == "dotnet-sdk-wrapped")
              packages
          );
        in
        {
          pname = package.pname or package.name;
          inherit (package) version;
        }
      '
  )" || fail 'could not render the workstation .NET SDK package'

  jq -e '
    (.pname == "dotnet-sdk-wrapped") and
    (.version | startswith("10."))
  ' <<<"$dotnet_sdk_package" >/dev/null \
    || fail 'rendered workstation package profile does not include the .NET 10 LTS SDK'
}

test_collie_origin_socket_listens_on_the_portal_origin_port() {
  local listen_stream

  listen_stream="$(
    rendered_raw '.collieOriginSocket.Socket.ListenStream' \
      "$REPO_ROOT#homeConfigurations.workstation.config.systemd.user.sockets.collie-origin-forwarder.Socket.ListenStream"
  )" || fail 'could not render the Collie origin socket listener'

  [[ "$listen_stream" == '0.0.0.0:8788' ]] \
    || fail "Collie origin socket listens on unexpected address: $listen_stream"
}

test_collie_origin_socket_activates_with_normal_user_sockets() {
  local wanted_by

  wanted_by="$(
    rendered_json '.collieOriginSocket.Install.WantedBy' \
      "$REPO_ROOT#homeConfigurations.workstation.config.systemd.user.sockets.collie-origin-forwarder.Install.WantedBy"
  )" || fail 'could not render the Collie origin socket activation target'

  [[ "$wanted_by" == '["sockets.target"]' ]] \
    || fail "Collie origin socket has unexpected activation targets: $wanted_by"
}

test_collie_origin_forwarder_connects_to_the_loopback_bridge() {
  local exec_start

  exec_start="$(
    rendered_json '.collieOriginService.Service.ExecStart' \
      "$REPO_ROOT#homeConfigurations.workstation.config.systemd.user.services.collie-origin-forwarder.Service.ExecStart"
  )" || fail 'could not render the Collie origin forwarder command'

  [[ "$exec_start" == '["/lib/systemd/systemd-socket-proxyd 127.0.0.1:8787"]' ]] \
    || fail "Collie origin forwarder has unexpected command: $exec_start"
}

test_collie_origin_forwarder_has_no_collie_service_dependency_or_fallback() {
  local rendered_service

  rendered_service="$(
    rendered_json '.collieOriginService' \
      "$REPO_ROOT#homeConfigurations.workstation.config.systemd.user.services.collie-origin-forwarder"
  )" || fail 'could not render the Collie origin forwarder service'

  jq -e '
    ((.Unit.Requires // []) == []) and
    ([((.Unit.After // [])[]) | select(test("collie"; "i"))] == []) and
    (.Service.ExecStart == ["/lib/systemd/systemd-socket-proxyd 127.0.0.1:8787"]) and
    (has("Install") | not)
  ' <<<"$rendered_service" >/dev/null \
    || fail 'Collie origin forwarder adds a Collie service dependency or fallback'
}

test_aoe_serve_pulls_up_its_origin_socket() {
  local rendered_service

  rendered_service="$(
    rendered_json '.aoeServeService' \
      "$REPO_ROOT#homeConfigurations.workstation.config.systemd.user.services.aoe-serve"
  )" || fail 'could not render the AoE serve service'

  # Starting aoe-serve without the socket leaves origin port 4001 unbound, so the
  # portal sees nothing while the app is healthy. Wants, not Requires: aoe-serve
  # stays useful locally if the socket fails, and Wants adds no ordering, so it
  # cannot deadlock against the proxy's own Requires=aoe-serve.service.
  jq -e '
    ([((.Unit.Wants // [])[]) | select(. == "aoe-lan-proxy.socket")] | length == 1) and
    ([((.Unit.Requires // [])[]) | select(test("aoe-lan-proxy"; "i"))] == []) and
    ([((.Unit.After // [])[]) | select(test("aoe-lan-proxy"; "i"))] == [])
  ' <<<"$rendered_service" >/dev/null \
    || fail 'aoe-serve does not softly pull up its origin socket'
}

test_collie_service_drop_in_pulls_up_its_origin_socket() {
  local rendered_drop_in

  rendered_drop_in="$(
    rendered_raw '.collieServiceDropIn' \
      "$REPO_ROOT#homeConfigurations.workstation.config.xdg.configFile.\"systemd/user/collie.service.d/10-origin-forwarder.conf\".text"
  )" || fail 'could not render the Collie service drop-in'

  # Collie's unit is generated by collie-ctl, so the link is expressed as a drop-in
  # rather than declared inline the way aoe-serve is. The drop-in must stay confined
  # to the socket dependency: anything reproducing the generated unit's ExecStart,
  # WorkingDirectory, or Environment would fork upstream's contract and drift on the
  # next Collie release.
  grep -Fxq '[Unit]' <<<"$rendered_drop_in" \
    || fail 'Collie drop-in is missing its [Unit] section'
  grep -Fxq 'Wants=collie-origin-forwarder.socket' <<<"$rendered_drop_in" \
    || fail 'Collie drop-in does not pull up the origin socket'
  if grep -Eq '^(ExecStart|WorkingDirectory|Environment|EnvironmentFile|Restart)=' \
    <<<"$rendered_drop_in"; then
    fail 'Collie drop-in reproduces generated unit contents instead of only the socket link'
  fi
}

test_existing_aoe_forwarder_rendering_is_unchanged() {
  local rendered_socket
  local rendered_service

  rendered_socket="$(
    rendered_json '.aoeLanProxySocket' \
      "$REPO_ROOT#homeConfigurations.workstation.config.systemd.user.sockets.aoe-lan-proxy"
  )" || fail 'could not render the existing AoE proxy socket'
  rendered_service="$(
    rendered_json '.aoeLanProxyService' \
      "$REPO_ROOT#homeConfigurations.workstation.config.systemd.user.services.aoe-lan-proxy"
  )" || fail 'could not render the existing AoE proxy service'

  jq -e '
    (.Socket.ListenStream == "0.0.0.0:4001") and
    (.Socket.NoDelay == true) and
    (.Install.WantedBy == ["sockets.target"])
  ' <<<"$rendered_socket" >/dev/null \
    || fail 'existing AoE proxy socket rendering changed'
  jq -e '
    (.Service.ExecStart == ["/lib/systemd/systemd-socket-proxyd 127.0.0.1:4000"]) and
    (.Unit.Requires == ["aoe-serve.service"]) and
    (.Unit.After == ["aoe-serve.service"])
  ' <<<"$rendered_service" >/dev/null \
    || fail 'existing AoE proxy service rendering changed'
}

# shellcheck source=tests/lib/suite-dispatch.bash
source "$REPO_ROOT/tests/lib/suite-dispatch.bash"

readonly test_cases=(
  test_workstation_profile_includes_dotnet_10_lts_sdk
  test_collie_origin_socket_listens_on_the_portal_origin_port
  test_collie_origin_socket_activates_with_normal_user_sockets
  test_collie_origin_forwarder_connects_to_the_loopback_bridge
  test_collie_origin_forwarder_has_no_collie_service_dependency_or_fallback
  test_aoe_serve_pulls_up_its_origin_socket
  test_collie_service_drop_in_pulls_up_its_origin_socket
  test_existing_aoe_forwarder_rendering_is_unchanged
)

suite_dispatch 'workstation Collie runtime and origin forwarder' "$@"
#!/usr/bin/env bash
set -uo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
readonly REPO_ROOT

fail() {
  printf 'ERROR: %s\n' "$*" >&2
  exit 2
}

readonly required_commands=(
  bash
  basename
  cat
  chezmoi
  chmod
  cp
  cut
  date
  diff
  dirname
  env
  find
  flock
  git
  git-upload-pack
  grep
  head
  install
  jq
  ln
  mkdir
  mktemp
  mv
  nix
  rm
  script
  sed
  sha256sum
  sleep
  sort
  stat
  tail
  tr
  unzip
  wc
  zip
)

missing_commands=()
for required_command in "${required_commands[@]}"; do
  command -v "$required_command" >/dev/null 2>&1 \
    || missing_commands+=("$required_command")
done
(( ${#missing_commands[@]} == 0 )) \
  || fail "required test dependencies not found in PATH: ${missing_commands[*]}"

# Invoked indirectly by the signal trap during a full run.
# shellcheck disable=SC2329
handle_interruption() {
  local child_pid

  trap - HUP INT TERM
  for child_pid in "${pids[@]}"; do
    kill -TERM -- "-$child_pid" 2>/dev/null || true
  done
  for child_pid in "${pids[@]}"; do
    wait "$child_pid" 2>/dev/null || true
  done
  exit 130
}

shopt -s nullglob
suites=("$REPO_ROOT"/tests/*.bash)
(( ${#suites[@]} > 0 )) || fail 'no test suites found'

declare -a cases=()
declare -A case_owner=()
declare -A suite_path_by_name=()
for suite_path in "${suites[@]}"; do
  suite_name="$(basename "$suite_path")"
  suite_path_by_name["$suite_name"]="$suite_path"
  if ! suite_cases="$(bash "$suite_path" --list)"; then
    fail "could not list cases for suite: $suite_name"
  fi
  while IFS= read -r test_case; do
    [[ -n "$test_case" ]] || continue
    if [[ -n "${case_owner[$test_case]:-}" ]]; then
      fail "ambiguous test case: $test_case"
    fi
    case_owner["$test_case"]="$suite_path"
    cases+=("$test_case")
  done <<<"$suite_cases"
done

if (( $# == 1 )) && [[ "$1" == --list ]]; then
  printf 'Suites:\n'
  for suite_path in "${suites[@]}"; do
    basename "$suite_path"
  done
  printf 'Cases:\n'
  printf '%s\n' "${cases[@]}"
  exit 0
fi

if (( $# == 2 )) && [[ "$1" == --suite && -n "$2" ]]; then
  selected_suite="${suite_path_by_name[$2]:-}"
  [[ -n "$selected_suite" ]] || fail "unknown test suite: $2"
  exec bash "$selected_suite"
fi

if (( $# == 2 )) && [[ "$1" == --case && -n "$2" ]]; then
  selected_suite="${case_owner[$2]:-}"
  [[ -n "$selected_suite" ]] || fail "unknown test case: $2"
  exec bash "$selected_suite" --case "$2"
fi

if (( $# == 0 )); then
  run_dir="$(mktemp -d "${TMPDIR:-/tmp}/dotfiles-tests.XXXXXX")" \
    || fail 'could not create temporary logging directory'
  trap 'rm -rf "$run_dir"' EXIT
  pids=()
  trap handle_interruption HUP INT TERM
  overall_start_ms="$(date +%s%3N)"
  starts_ms=()
  statuses=()
  durations_ms=()
  declare -A suite_index_by_pid=()
  set -m
  for suite_index in "${!suites[@]}"; do
    suite_path="${suites[$suite_index]}"
    starts_ms[suite_index]="$(date +%s%3N)"
    bash "$suite_path" >"$run_dir/$suite_index.log" 2>&1 &
    child_pid="$!"
    pids+=("$child_pid")
    suite_index_by_pid["$child_pid"]="$suite_index"
  done
  set +m

  aggregate_status=0
  passed_count=0
  failed_count=0
  remaining_count="${#pids[@]}"
  while (( remaining_count > 0 )); do
    completed_pid=
    if wait -n -p completed_pid; then
      completion_status=0
    else
      completion_status=$?
    fi
    [[ -n "$completed_pid" ]] \
      || fail 'could not identify a completed test suite'
    suite_index="${suite_index_by_pid[$completed_pid]}"
    if (( completion_status == 0 )); then
      statuses[suite_index]=0
      passed_count=$((passed_count + 1))
    else
      statuses[suite_index]="$completion_status"
      aggregate_status=1
      failed_count=$((failed_count + 1))
    fi
    end_ms="$(date +%s%3N)"
    durations_ms[suite_index]=$((end_ms - starts_ms[suite_index]))
    remaining_count=$((remaining_count - 1))
  done

  if (( failed_count > 0 )); then
    printf 'Failures:\n'
    for suite_index in "${!suites[@]}"; do
      (( statuses[suite_index] != 0 )) || continue
      suite_name="$(basename "${suites[$suite_index]}")"
      printf '===== %s (status %s) =====\n' \
        "$suite_name" "${statuses[$suite_index]}"
      cat "$run_dir/$suite_index.log"
      printf '===== end %s =====\n' "$suite_name"
    done
  fi

  printf 'Results:\n'
  for suite_index in "${!suites[@]}"; do
    suite_name="$(basename "${suites[$suite_index]}")"
    if (( statuses[suite_index] == 0 )); then
      printf 'PASS %s (%sms)\n' \
        "$suite_name" "${durations_ms[$suite_index]}"
    else
      printf 'FAIL %s (%sms, status %s)\n' \
        "$suite_name" \
        "${durations_ms[$suite_index]}" \
        "${statuses[$suite_index]}"
    fi
  done
  overall_end_ms="$(date +%s%3N)"
  overall_duration_ms=$((overall_end_ms - overall_start_ms))
  if (( aggregate_status == 0 )); then
    printf 'Overall: PASS (%s passed, 0 failed, %sms)\n' \
      "$passed_count" "$overall_duration_ms"
  else
    printf 'Overall: FAIL (%s passed, %s failed, %sms)\n' \
      "$passed_count" "$failed_count" "$overall_duration_ms"
  fi
  exit "$aggregate_status"
fi

